func (st *ServerType) makeMatcherModule(definitionName, matcherName string, tokens []caddyfile.Token) error {
	if st.namedMatchers == nil {
		st.namedMatchers = &namedMatcherState{}
	}
	st.namedMatchers.currentName = definitionName
	st.namedMatchers.pendingTokens = tokens
	if st.namedMatchers.defs == nil {
		st.namedMatchers.defs = make(map[string]caddy.ModuleMap)
	}

	// create a new dispenser from the tokens
	dispenser := caddyfile.NewDispenser(tokens)

	// set the matcher name (without @) in the dispenser context so
	// that matcher modules can access it to use it as their name
	// (e.g. regexp matchers which use the name for capture groups)
	dispenser.SetContext(caddyfile.MatcherNameCtxKey, definitionName[1:])

	mod, err := caddy.GetModule("http.matchers." + matcherName)
	if err != nil {
		return fmt.Errorf("getting matcher module '%s': %v", matcherName, err)
	}
	unm, ok := mod.New().(caddyfile.Unmarshaler)
	if !ok {
		return fmt.Errorf("matcher module '%s' is not a Caddyfile unmarshaler", matcherName)
	}
	err = unm.UnmarshalCaddyfile(dispenser)
	if err != nil {
		return err
	}
	rm, ok := unm.(caddyhttp.RequestMatcher)
	if !ok {
		return fmt.Errorf("matcher module '%s' is not a request matcher", matcherName)
	}
	st.namedMatchers.defs[definitionName][matcherName] = caddyconfig.JSON(rm, nil)
	return nil
}

func encodeMatcherSet(matchers map[string]caddyhttp.RequestMatcher) (caddy.ModuleMap, error) {
	return new(ServerType).encodeMatcherSet(matchers)
}

func (st *ServerType) encodeMatcherSet(matchers map[string]caddyhttp.RequestMatcher) (caddy.ModuleMap, error) {
	if st.namedMatchers == nil {
		st.namedMatchers = &namedMatcherState{}
	}
	msEncoded := make(caddy.ModuleMap)
	for matcherName, val := range matchers {
		jsonBytes, err := json.Marshal(val)
		if err != nil {
			return nil, fmt.Errorf("marshaling matcher set %#v: %v", matchers, err)
		}
		msEncoded[matcherName] = jsonBytes
	}
	st.namedMatchers.encoded = msEncoded
	return msEncoded, nil
}

