// expressionMatcherTokens synthesizes the implicit "expression" matcher
// name token in front of a quoted CEL expression.
func (st *ServerType) expressionMatcherTokens(d *caddyfile.Dispenser) []caddyfile.Token {
	if st.namedMatchers == nil {
		st.namedMatchers = &namedMatcherState{}
	}
	// we clone the token to make the new token to keep the same
	// import location as the next token, if this is within a snippet
	// or imported file; otherwise the tokens would appear to be on
	// different lines, which would break parsing
	// see https://github.com/caddyserver/caddy/issues/6287
	expressionToken := d.Token().Clone()
	expressionToken.Text = "expression"
	tokens := []caddyfile.Token{
		expressionToken,
		d.Token(),
	}
	st.namedMatchers.pendingTokens = tokens
	return tokens
}

